1	import * as THREE from "three";
2	import {
3	  aboutLights as aboutLightsId,
4	  earth as earthId,
5	} from "../../../core/setup.js";
6	import type { Engine } from "../../../core/Engine.js";
7	import type { SceneFromState } from "../../../types/core.types.js";
8	import type {
9	  ContactCameraTheatreValue,
10	  ContactLightsPort,
11	  ContactSceneState,
12	  ContactTransformState,
13	} from "../../../types/contact.types.js";
14	import { Helpers } from "../../../utils/Helpers.js";
15	import { CONTACT_DEFAULT_SCENE_STATE } from "../scene/contact.scene.js";
16	
17	export class ContactSceneRig {
18	  createDefaultValue(): ContactSceneState {
19	    return {
20	      camera: {
21	        position: { ...CONTACT_DEFAULT_SCENE_STATE.camera.position },
22	        target: { ...CONTACT_DEFAULT_SCENE_STATE.camera.target },
23	        fov: CONTACT_DEFAULT_SCENE_STATE.camera.fov,
24	      },
25	      light: {
26	        ...CONTACT_DEFAULT_SCENE_STATE.light,
27	        rig: {
28	          position: { ...CONTACT_DEFAULT_SCENE_STATE.light.rig.position },
29	          rotation: { ...CONTACT_DEFAULT_SCENE_STATE.light.rig.rotation },
30	          scale: { ...CONTACT_DEFAULT_SCENE_STATE.light.rig.scale },
31	          visible: CONTACT_DEFAULT_SCENE_STATE.light.rig.visible,
32	        },
33	      },
34	      earth: {
35	        position: { ...CONTACT_DEFAULT_SCENE_STATE.earth.position },
36	        rotation: { ...CONTACT_DEFAULT_SCENE_STATE.earth.rotation },
37	        scale: { ...CONTACT_DEFAULT_SCENE_STATE.earth.scale },
38	        visible: CONTACT_DEFAULT_SCENE_STATE.earth.visible,
39	      },
40	    };
41	  }
42	
43	  compose(state: ContactSceneState): SceneFromState {
44	    return {
45	      camera: {
46	        position: { ...state.camera.position },
47	        fov: state.camera.fov,
48	      },
49	      cameraTarget: {
50	        position: { ...state.camera.target },
51	      },
52	      [earthId]: state.earth,
53	    } as unknown as SceneFromState;
54	  }
55	
56	  apply(engine: Engine, state: ContactSceneState): void {
57	    engine.setState(this.compose(state));
58	    engine.getCamera().lookAt(engine.getCameraTarget().position);
59	    this._applyLight(engine, state.light);
60	  }
61	
62	  read(engine: Engine): ContactSceneState {
63	    const camera = engine.getCamera();
64	    const target = engine.getCameraTarget();
65	    const defaults = CONTACT_DEFAULT_SCENE_STATE;
66	    return {
67	      camera: {
68	        position: {
69	          x: this._toFinite(camera.position.x, defaults.camera.position.x),
70	          y: this._toFinite(camera.position.y, defaults.camera.position.y),
71	          z: this._toFinite(camera.position.z, defaults.camera.position.z),
72	        },
73	        target: {
74	          x: this._toFinite(target.position.x, defaults.camera.target.x),
75	          y: this._toFinite(target.position.y, defaults.camera.target.y),
76	          z: this._toFinite(target.position.z, defaults.camera.target.z),
77	        },
78	        fov: this._toFinite(camera.fov, defaults.camera.fov),
79	      },
80	      light: this._readLight(engine),
81	      earth: this._readTransform(engine, earthId, defaults.earth),
82	    };
83	  }
84	
85	  readCamera(engine: Engine): ContactCameraTheatreValue {
86	    return {
87	      camera: this.read(engine).camera,
88	    };
89	  }
90	
91	  readObjectValue(value: ContactSceneState): ContactSceneState {
92	    return {
93	      camera: {
94	        position: { ...value.camera.position },
95	        target: { ...value.camera.target },
96	        fov: value.camera.fov,
97	      },
98	      light: {
99	        ...value.light,
100	        rig: {
101	          position: { ...value.light.rig.position },
102	          rotation: { ...value.light.rig.rotation },
103	          scale: { ...value.light.rig.scale },
104	          visible: value.light.rig.visible,
105	        },
106	      },
107	      earth: {
108	        position: { ...value.earth.position },
109	        rotation: { ...value.earth.rotation },
110	        scale: { ...value.earth.scale },
111	        visible: value.earth.visible,
112	      },
113	    };
114	  }
115	
116	  private _applyLight(
117	    engine: Engine,
118	    state: ContactSceneState["light"],
119	  ): void {
120	    const light = engine.getSceneObjectById(
121	      aboutLightsId,
122	    ) as ContactLightsPort | null;
123	    if (!light) return;
124	    light.setState(state);
125	  }
126	
127	  private _readLight(engine: Engine): ContactSceneState["light"] {
128	    const light = engine.getSceneObjectById(
129	      aboutLightsId,
130	    ) as ContactLightsPort | null;
131	    if (!light) {
132	      return {
133	        ...CONTACT_DEFAULT_SCENE_STATE.light,
134	        rig: {
135	          position: { ...CONTACT_DEFAULT_SCENE_STATE.light.rig.position },
136	          rotation: { ...CONTACT_DEFAULT_SCENE_STATE.light.rig.rotation },
137	          scale: { ...CONTACT_DEFAULT_SCENE_STATE.light.rig.scale },
138	          visible: CONTACT_DEFAULT_SCENE_STATE.light.rig.visible,
139	        },
140	      };
141	    }
142	    return light.getState();
143	  }
144	
145	  private _readTransform(
146	    engine: Engine,
147	    id: string,
148	    fallback: ContactTransformState,
149	  ): ContactTransformState {
150	    const target = engine.getObjectById(id) as THREE.Object3D | null;
151	    const rotation = Helpers.readRotationDeg(target);
152	    return {
153	      position: {
154	        x: this._toFinite(target?.position.x, fallback.position.x),
155	        y: this._toFinite(target?.position.y, fallback.position.y),
156	        z: this._toFinite(target?.position.z, fallback.position.z),
157	      },
158	      rotation: {
159	        x: this._toFinite(rotation.x, fallback.rotation.x),
160	        y: this._toFinite(rotation.y, fallback.rotation.y),
161	        z: this._toFinite(rotation.z, fallback.rotation.z),
162	      },
163	      scale: {
164	        x: this._toFinite(target?.scale.x, fallback.scale.x),
165	        y: this._toFinite(target?.scale.y, fallback.scale.y),
166	        z: this._toFinite(target?.scale.z, fallback.scale.z),
167	      },
168	      visible: target?.visible ?? fallback.visible,
169	    };
170	  }
171	
172	  private _toFinite(value: unknown, fallback: number): number {
173	    if (typeof value !== "number") return fallback;
174	    if (!Number.isFinite(value)) return fallback;
175	    return value;
176	  }
177	}
