201	function _easeInOut(t: number): number {
202	  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
203	}
204	
205	function _clamp01(v: number): number {
206	  return v < 0 ? 0 : v > 1 ? 1 : v;
207	}
208	
209	function _rangeAlpha(p: number, inStart: number, inEnd: number, outStart: number, outEnd: number): number {
210	  if (p < inStart) return 0;
211	  if (p < inEnd) return _easeInOut(_clamp01((p - inStart) / (inEnd - inStart)));
212	  if (p < outStart) return 1;
213	  if (p < outEnd) return _easeInOut(_clamp01(1 - (p - outStart) / (outEnd - outStart)));
214	  return 0;
215	}
