217	function syncProofHeadlines(progress: number): void {
218	  const h1 = document.querySelector<HTMLElement>(PROOF_H1_SELECTOR);
219	  const h2 = document.querySelector<HTMLElement>(PROOF_H2_SELECTOR);
220	  if (!h1 || !h2) return;
221	
222	  const a1 = _rangeAlpha(progress, 0, 0.15, 0.45, 0.6);
223	  const a2 = _rangeAlpha(progress, 0.45, 0.6, 1.1, 1.1);
224	
225	  h1.style.opacity = String(a1);
226	  h1.style.filter = `blur(${(1 - a1) * PROOF_BLUR_PX}px)`;
227	  h2.style.opacity = String(a2);
228	  h2.style.filter = `blur(${(1 - a2) * PROOF_BLUR_PX}px)`;
