309	    if (!force && now - this._lastSampleAt < FRAME_MS) return;
310	    this._lastSampleAt = now;
311	    const values = this._readCameraValues();
312	    const cameraScrub = scrub as unknown as ContactTheatreScrubCameraPort;
313	    cameraScrub.capture(({ set }) => {
