257	  private _playSheetAutoplayWithGsap(
258	    engine: Engine,
259	    binding: ContactTheatreSheetBinding,
260	    playbackRange: ContactTheatrePlaybackRange,
261	    durationMs: number,
262	    gsap: GsapGlobal,
263	  ): Promise<void> {
264	    return new Promise<void>((resolve) => {
265	      const state = { position: playbackRange.start };
266	      gsap.killTweensOf?.(state);
267	      gsap.to(state, {
268	        position: playbackRange.end,
269	        duration: durationMs / 1000,
270	        ease: CONTACT_THEATRE_AUTOPLAY_EASE,
271	        onUpdate: () => {
272	          binding.sequence.position = state.position;
273	          this._rig.apply(engine, binding.object.value);
274	        },
275	        onComplete: () => {
276	          binding.sequence.position = playbackRange.end;
277	          this._rig.apply(engine, binding.object.value);
278	          resolve();
279	        },
280	      });
281	    });
282	  }
